import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";
import styled from "styled-components";
import { Helmet } from "react-helmet-async";
import { seo } from "../../portfolio";

const HeaderContainer = styled.header`
  background-color: ${({ theme }) => theme.surface};
  border-bottom: 1px solid ${({ theme }) => theme.border};
  position: sticky;
  top: 0;
  z-index: ${({ theme }) => theme.zIndex.fixed};
  box-shadow: ${({ theme }) => theme.shadowSm};
`;

const HeaderContent = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 ${({ theme }) => theme.spacing.lg};
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 70px;

  @media (max-width: 768px) {
    padding: 0 ${({ theme }) => theme.spacing.md};
    height: 60px;
  }
`;

const Logo = styled(Link)`
  font-size: 1.5rem;
  font-weight: 700;
  color: ${({ theme }) => theme.primary};
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.sm};
  transition: opacity ${({ theme }) => theme.transitionFast};

  &:hover {
    opacity: 0.8;
  }

  span.bracket {
    color: ${({ theme }) => theme.secondary};
  }
`;

const Nav = styled.nav`
  display: flex;
  gap: ${({ theme }) => theme.spacing.lg};

  @media (max-width: 768px) {
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    flex-direction: column;
    background-color: ${({ theme }) => theme.surface};
    border-bottom: 1px solid ${({ theme }) => theme.border};
    padding: ${({ theme }) => theme.spacing.md};
    gap: 0;
    max-height: ${({ isOpen }) => (isOpen ? "400px" : "0")};
    overflow: hidden;
    transition: max-height ${({ theme }) => theme.transitionBase};
    box-shadow: ${({ theme }) => theme.shadowMd};
  }
`;

const NavLink = styled(Link)`
  color: ${({ theme, isActive }) =>
    isActive ? theme.secondary : theme.textPrimary};
  font-weight: ${({ isActive }) => (isActive ? "600" : "500")};
  padding: ${({ theme }) => `${theme.spacing.sm} ${theme.spacing.md}`};
  border-bottom: 2px solid
    ${({ theme, isActive }) => (isActive ? theme.secondary : "transparent")};
  transition: all ${({ theme }) => theme.transitionFast};

  &:hover {
    color: ${({ theme }) => theme.secondary};
    border-bottom-color: ${({ theme }) => theme.secondary};
  }

  @media (max-width: 768px) {
    border-bottom: none;
    border-left: 3px solid
      ${({ theme, isActive }) => (isActive ? theme.secondary : "transparent")};
    padding: ${({ theme }) => `${theme.spacing.md} ${theme.spacing.lg}`};
  }
`;

const MobileMenuButton = styled.button`
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  color: ${({ theme }) => theme.primary};
  cursor: pointer;
  padding: ${({ theme }) => theme.spacing.sm};

  @media (max-width: 768px) {
    display: block;
  }
`;

export default function Header() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const location = useLocation();

  const isActive = (path) => location.pathname === path;

  const toggleMobileMenu = () => {
    setMobileMenuOpen(!mobileMenuOpen);
  };

  return (
    <>
      <Helmet>
        <title>{seo.title}</title>
        <meta name="description" content={seo.description} />
        <meta property="og:title" content={seo.og.title} />
        <meta property="og:description" content={seo.og.description} />
        <meta property="og:type" content={seo.og.type} />
        <meta property="og:url" content={seo.og.url} />
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:title" content={seo.og.title} />
        <meta name="twitter:description" content={seo.og.description} />
        <link rel="canonical" href={seo.og.url} />
      </Helmet>

      <HeaderContainer>
        <HeaderContent>
          <Logo to="/">
            <span className="bracket">&lt;</span>
            <span>Zacharia</span>
            <span className="bracket">/&gt;</span>
          </Logo>

          <Nav isOpen={mobileMenuOpen}>
            <NavLink to="/" isActive={isActive("/")} onClick={() => setMobileMenuOpen(false)}>
              Home
            </NavLink>
            <NavLink to="/experience" isActive={isActive("/experience")} onClick={() => setMobileMenuOpen(false)}>
              Experience
            </NavLink>
            <NavLink to="/contact" isActive={isActive("/contact")} onClick={() => setMobileMenuOpen(false)}>
              Contact
            </NavLink>
          </Nav>

          <MobileMenuButton onClick={toggleMobileMenu}>
            {mobileMenuOpen ? "✕" : "☰"}
          </MobileMenuButton>
        </HeaderContent>
      </HeaderContainer>
    </>
  );
}
