import React from "react";
import { Helmet } from "react-helmet-async";
import styled from "styled-components";
import Header from "../../components/header/Header";
import Footer from "../../components/footer/Footer";
import { contactPageData, seo, socialMediaLinks } from "../../portfolio";

const Container = styled.div`
  min-height: 100vh;
  display: flex;
  flex-direction: column;
`;

const Main = styled.main`
  flex: 1;
  max-width: 800px;
  width: 100%;
  margin: 0 auto;
  padding: ${({ theme }) => theme.spacing.xxxl} ${({ theme }) => theme.spacing.lg};

  @media (max-width: 768px) {
    padding: ${({ theme }) => theme.spacing.xxl} ${({ theme }) => theme.spacing.md};
  }
`;

const PageTitle = styled.h1`
  font-size: 2.5rem;
  margin-bottom: ${({ theme }) => theme.spacing.lg};
  text-align: center;
  color: ${({ theme }) => theme.primary};
`;

const ContactCard = styled.div`
  background-color: ${({ theme }) => theme.surface};
  border: 1px solid ${({ theme }) => theme.border};
  border-radius: ${({ theme }) => theme.radiusLg};
  padding: ${({ theme }) => theme.spacing.xxl};
  margin-bottom: ${({ theme }) => theme.spacing.xxl};
`;

const ContactTitle = styled.h2`
  font-size: 1.5rem;
  color: ${({ theme }) => theme.secondary};
  margin-bottom: ${({ theme }) => theme.spacing.md};
`;

const ContactDescription = styled.p`
  color: ${({ theme }) => theme.textSecondary};
  line-height: 1.7;
  margin-bottom: ${({ theme }) => theme.spacing.lg};
`;

const ContactInfo = styled.div`
  color: ${({ theme }) => theme.textPrimary};
  font-size: 1.1rem;
  margin-bottom: ${({ theme }) => theme.spacing.md};

  strong {
    display: block;
    margin-bottom: ${({ theme }) => theme.spacing.sm};
    color: ${({ theme }) => theme.secondary};
  }

  a {
    color: ${({ theme }) => theme.secondary};
    text-decoration: none;

    &:hover {
      text-decoration: underline;
    }
  }
`;

const SocialLinks = styled.div`
  display: flex;
  gap: ${({ theme }) => theme.spacing.md};
  margin-top: ${({ theme }) => theme.spacing.lg};
  flex-wrap: wrap;
`;

const SocialIcon = styled.a`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  border-radius: ${({ theme }) => theme.radiusMd};
  background-color: ${({ theme }) => theme.surfaceAlt};
  color: ${({ theme }) => theme.primary};
  font-size: 1.3rem;
  transition: all ${({ theme }) => theme.transitionBase};

  &:hover {
    background-color: ${({ theme }) => theme.secondary};
    color: white;
    transform: translateY(-3px);
  }

  i {
    margin: 0;
  }
`;

export default function Contact() {
  return (
    <Container>
      <Helmet>
        <title>Contact | {seo.title}</title>
        <meta name="description" content={`Contact: ${seo.description}`} />
      </Helmet>

      <Header />

      <Main>
        <PageTitle>Get In Touch</PageTitle>

        <ContactCard>
          <ContactTitle>{contactPageData.contactSection.title}</ContactTitle>
          <ContactDescription>{contactPageData.contactSection.description}</ContactDescription>

          <ContactInfo>
            <strong>Email</strong>
            <a href={`mailto:${contactPageData.contactSection.email}`}>
              {contactPageData.contactSection.email}
            </a>
          </ContactInfo>

          <ContactInfo>
            <strong>Phone</strong>
            <a href={`tel:${contactPageData.contactSection.phone}`}>
              {contactPageData.contactSection.phone}
            </a>
          </ContactInfo>

          <ContactInfo>
            <strong>Location</strong>
            <a
              href={contactPageData.addressSection.location_map_link}
              target="_blank"
              rel="noreferrer"
            >
              {contactPageData.addressSection.subtitle}
            </a>
          </ContactInfo>

          <div>
            <strong style={{ display: "block", marginBottom: "1rem" }}>Connect</strong>
            <SocialLinks>
              {socialMediaLinks.map((link, idx) => (
                <SocialIcon
                  key={idx}
                  href={link.link}
                  target="_blank"
                  rel="noreferrer"
                  title={link.name}
                >
                  <i className={link.fontAwesomeIcon}></i>
                </SocialIcon>
              ))}
            </SocialLinks>
          </div>
        </ContactCard>
      </Main>

      <Footer />
    </Container>
  );
}
