import React from "react";
import { Helmet } from "react-helmet-async";
import styled from "styled-components";
import Header from "../../components/header/Header";
import Footer from "../../components/footer/Footer";
import { experience, seo } from "../../portfolio";

const Container = styled.div`
  min-height: 100vh;
  display: flex;
  flex-direction: column;
`;

const Main = styled.main`
  flex: 1;
  max-width: 1000px;
  width: 100%;
  margin: 0 auto;
  padding: ${({ theme }) => theme.spacing.xxxl} ${({ theme }) => theme.spacing.lg};

  @media (max-width: 768px) {
    padding: ${({ theme }) => theme.spacing.xxl} ${({ theme }) => theme.spacing.md};
  }
`;

const PageTitle = styled.h1`
  font-size: 2.5rem;
  margin-bottom: ${({ theme }) => theme.spacing.lg};
  color: ${({ theme }) => theme.primary};
`;

const Section = styled.section`
  margin-bottom: ${({ theme }) => theme.spacing.xxxl};

  &:not(:last-child) {
    padding-bottom: ${({ theme }) => theme.spacing.xxl};
    border-bottom: 1px solid ${({ theme }) => theme.border};
  }
`;

const SectionTitle = styled.h2`
  font-size: 1.8rem;
  margin-bottom: ${({ theme }) => theme.spacing.xxl};
  color: ${({ theme }) => theme.textPrimary};
`;

const ExperienceCard = styled.div`
  background-color: ${({ theme }) => theme.surface};
  border-left: 4px solid ${({ theme }) => theme.secondary};
  border-radius: ${({ theme }) => theme.radiusMd};
  padding: ${({ theme }) => theme.spacing.lg};
  margin-bottom: ${({ theme }) => theme.spacing.lg};
  transition: all ${({ theme }) => theme.transitionBase};

  &:hover {
    box-shadow: ${({ theme }) => theme.shadowMd};
    transform: translateX(4px);
  }
`;

const ExperienceTitle = styled.h3`
  font-size: 1.3rem;
  color: ${({ theme }) => theme.secondary};
  margin-bottom: ${({ theme }) => theme.spacing.sm};
`;

const ExperienceMeta = styled.p`
  display: flex;
  flex-wrap: wrap;
  gap: ${({ theme }) => theme.spacing.md};
  margin-bottom: ${({ theme }) => theme.spacing.md};
  font-size: 0.95rem;
  color: ${({ theme }) => theme.textTertiary};

  strong {
    color: ${({ theme }) => theme.textSecondary};
  }
`;

const ExperienceDescription = styled.p`
  color: ${({ theme }) => theme.textSecondary};
  line-height: 1.7;
  margin-bottom: ${({ theme }) => theme.spacing.md};
`;

const HighlightList = styled.ul`
  list-style: none;
  padding: 0;
  margin-top: ${({ theme }) => theme.spacing.md};

 li {
    padding: ${({ theme }) => theme.spacing.sm} 0;
    padding-left: ${({ theme }) => theme.spacing.md};
    position: relative;
    color: ${({ theme }) => theme.textSecondary};
    font-size: 0.95rem;

    &:before {
      content: "✓";
      position: absolute;
      left: 0;
      color: ${({ theme }) => theme.secondary};
      font-weight: bold;
    }
  }
`;

export default function Experience() {
  return (
    <Container>
      <Helmet>
        <title>Experience | {seo.title}</title>
        <meta name="description" content={`Career experience: ${seo.description}`} />
      </Helmet>

      <Header />

      <Main>
        <PageTitle>Career Experience</PageTitle>

        {experience.sections.map((section, idx) => (
          <Section key={idx}>
            <SectionTitle>{section.title}</SectionTitle>
            {section.experiences.map((exp, expIdx) => (
              <ExperienceCard key={expIdx}>
                <ExperienceTitle>{exp.title}</ExperienceTitle>
                <ExperienceMeta>
                  <span>
                    <strong>{exp.company}</strong>
                  </span>
                  {exp.duration && <span>{exp.duration}</span>}
                  {exp.location && <span>{exp.location}</span>}
                </ExperienceMeta>
                <ExperienceDescription>{exp.description}</ExperienceDescription>
                {exp.highlights && (
                  <HighlightList>
                    {exp.highlights.map((highlight, hIdx) => (
                      <li key={hIdx}>{highlight}</li>
                    ))}
                  </HighlightList>
                )}
              </ExperienceCard>
            ))}
          </Section>
        ))}
      </Main>

      <Footer />
    </Container>
  );
}
